import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, fract, sin, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'home-floating-accent';

  // Atlas region 512x320 -> aspect ratio
  const rect = { w: 512, h: 320 };
  const aspect = rect.w / rect.h;
  const planeHeight = 2.6;
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight, 1, 1);

  // Placeholder material until texture resolves — kept transparent so no flash of gray.
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  material.opacity = 0.0;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'home-floating-accent-plane';
  group.add(mesh);

  let disposed = false;
  let loadedTexture = null;

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    if (disposed) return;
    loadedTexture = tex;

    const texNode = texture(tex);

    // Subtle engineered grain — dot-hash noise, centered and low-amplitude.
    const grainSeed = dot(uv(), vec2(12.9898, 78.233));
    const grainRaw = fract(sin(grainSeed).mul(43758.5453));
    const grainNode = grainRaw.sub(0.5).mul(0.035);

    material.colorNode = texNode.rgb.add(grainNode);
    material.opacityNode = texNode.a;
    material.transparent = true;
    material.needsUpdate = true;
    material.opacity = 1.0;

    // Weighted-settle entrance: overshoot 1.04 -> 1.0, translate-in, fade-up.
    group.scale.set(0.92, 0.92, 0.92);
    mesh.position.y = -0.15;

    const tl = gsap.timeline();
    tl.to(material, { opacity: 1.0, duration: 0.6, ease: 'power2.out' });
    tl.to(
      group.scale,
      { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power3.out' },
      0
    );
    tl.to(
      group.scale,
      { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' },
      0.5
    );
    tl.to(
      mesh.position,
      { y: 0, duration: 0.9, ease: 'power4.out' },
      0
    );

    // Idle breathing — one slow transform, amplitude within 2%.
    const idle = gsap.to(group.scale, {
      x: 1.015,
      y: 1.015,
      z: 1.015,
      duration: 4.2,
      ease: 'sine.inOut',
      yoyo: true,
      repeat: -1,
      delay: 1.4,
    });

    timelines.push(tl, idle);
  });

  const timelines = [];

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    disposed = true;
    for (const tl of timelines) {
      if (tl && typeof tl.kill === 'function') tl.kill();
    }
    timelines.length = 0;
    geometry.dispose();
    material.dispose();
    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }
  };

  return group;
}
